//! Deterministic Rust emitters. Same input bytes ⇒ same output bytes.

use std::{collections::BTreeMap, fmt::Write as _};

use crate::{
    allow_list::REGISTER_ALLOW_LIST,
    parse::{ParseError, Register, parse_evaluable_defines},
};

/// Upstream commit recorded in `UPSTREAM`, embedded in generated file headers.
pub struct GenMeta<'a> {
    pub commit: &'a str,
}

fn fmt_u64_hex(v: u64) -> String {
    // Always 16 hex digits, groups of 4, lowercase — matches the hand-written seed.
    let s = format!("{v:016x}");
    let mut out = String::from("0x");
    for (i, chunk) in s.as_bytes().chunks(4).enumerate() {
        if i > 0 {
            out.push('_');
        }
        out.push_str(std::str::from_utf8(chunk).unwrap());
    }
    out
}

fn fmt_offset(v: u32) -> String {
    if v <= 0xffff {
        format!("0x{v:04x}")
    } else {
        format!("0x{v:x}")
    }
}

/// `ROGUE_CR_CORE_ID__PBVNC` → `core_id_pbvnc`
pub fn rust_mod_name(reg_name: &str) -> String {
    let rest = reg_name
        .strip_prefix("ROGUE_CR_")
        .unwrap_or(reg_name)
        .replace("__", "_");
    rest.to_ascii_lowercase()
}

/// Emit `src/rogue/cr.rs`.
pub fn emit_cr(
    regs: &BTreeMap<String, Register>,
    meta: &GenMeta<'_>,
) -> Result<String, ParseError> {
    let mut out = String::new();
    out.push_str("// SPDX-License-Identifier: MIT OR GPL-2.0-only\n");
    out.push_str("// Copyright (c) 2023 Imagination Technologies Ltd.\n");
    out.push_str("// K1 MUSE Book: generated PowerVR register and firmware ABI definitions.\n");
    out.push_str("//\n");
    out.push_str("// GENERATED by `pvr-regen` — DO NOT EDIT BY HAND.\n");
    out.push_str("// Source: pvr_rogue_cr_defs.h, pvr_rogue_cr_defs_client.h\n");
    writeln!(out, "// Upstream commit: {}", meta.commit).unwrap();
    out.push_str(
        "// Re-run: cargo run --manifest-path kernel/core/comps/k1-musebook/pvr/regen/Cargo.toml\n",
    );
    out.push_str("//\n");
    out.push_str("// Dead code is expected: the allow-list tracks every register the\n");
    out.push_str("// upstream .c files reference, while the Rust port only uses a\n");
    out.push_str("// subset so far. Missing an allow-listed register is a regen error;\n");
    out.push_str("// an unused generated item is not.\n");
    out.push_str("#![allow(dead_code)]\n");
    out.push_str("// Upstream keeps occasional lowercase letters in macro names (e.g. Dust_n);\n");
    out.push_str("// we preserve the spelling for grep-ability against the headers.\n");
    out.push_str("#![allow(non_upper_case_globals)]\n");
    out.push('\n');
    out.push_str("//! GPU control-register offsets and bitfields.\n");
    out.push_str("//!\n");
    out.push_str(
        "//! Upstream defines each register as a base offset plus, per field, a shift, a\n",
    );
    out.push_str(
        "//! mask and a clear-mask. The generator collapses that into one [`Field`] const\n",
    );
    out.push_str(
        "//! per field so that a misuse is a type error rather than a silently wrong shift.\n",
    );
    out.push_str("//!\n");
    out.push_str("//! Only the registers the driver touches are emitted. See the subset rule in\n");
    out.push_str("//! [`super`].\n");
    out.push('\n');
    out.push_str("/// A bitfield within a 64-bit control register.\n");
    out.push_str("#[derive(Clone, Copy, Debug)]\n");
    out.push_str("pub struct Field {\n");
    out.push_str("    /// Bit position of the least significant bit.\n");
    out.push_str("    pub shift: u32,\n");
    out.push_str("    /// Mask of the field, already positioned at [`Self::shift`].\n");
    out.push_str("    pub mask: u64,\n");
    out.push_str("}\n");
    out.push('\n');
    out.push_str("impl Field {\n");
    out.push_str("    /// Extracts this field from a register value.\n");
    out.push_str("    pub const fn get(self, reg: u64) -> u64 {\n");
    out.push_str("        (reg & self.mask) >> self.shift\n");
    out.push_str("    }\n");
    out.push('\n');
    out.push_str("    /// Returns `reg` with this field replaced by `value`.\n");
    out.push_str("    pub const fn set(self, reg: u64, value: u64) -> u64 {\n");
    out.push_str("        (reg & !self.mask) | ((value << self.shift) & self.mask)\n");
    out.push_str("    }\n");
    out.push_str("}\n");

    for entry in REGISTER_ALLOW_LIST {
        let Some(reg) = regs.get(entry.name) else {
            return Err(ParseError(format!(
                "allow-list register `{}` not found in headers ({})",
                entry.name, entry.why
            )));
        };
        out.push('\n');
        emit_register_module(&mut out, reg)?;
    }
    Ok(out)
}

fn emit_register_module(out: &mut String, reg: &Register) -> Result<(), ParseError> {
    let mod_name = rust_mod_name(&reg.name);

    // Hand-written seed docs/shape for the round-trip check. Must stay
    // byte-identical to the pre-generator `core_id_pbvnc` module.
    if reg.name == "ROGUE_CR_CORE_ID__PBVNC" {
        out.push_str("/// `RGX_CR_CORE_ID` in its packed BVNC form.\n");
        out.push_str("///\n");
        out.push_str(
            "/// This is the first register the driver reads, before it knows anything else\n",
        );
        out.push_str(
            "/// about the GPU, and it is what makes the driver GPU-agnostic: branch, version,\n",
        );
        out.push_str("/// scalable-unit count and config all come from here rather than from a\n");
        out.push_str("/// compiled-in table.\n");
        out.push_str("pub mod core_id_pbvnc {\n");
        out.push_str("    use super::Field;\n");
        out.push('\n');
        // Cross-checked like the seed fields below: emit the parsed offset rather
        // than a literal, so a header change cannot slip past the round-trip.
        if reg.offset != 0x0020 {
            return Err(ParseError(format!(
                "seed register {}: parsed offset {} but seed expects 0x0020",
                reg.name,
                fmt_offset(reg.offset)
            )));
        }
        out.push_str("    /// Register offset.\n");
        writeln!(
            out,
            "    pub const OFFSET: u32 = {};",
            fmt_offset(reg.offset)
        )
        .unwrap();
        emit_seed_field(out, reg, "BRANCH_ID", "Branch ID. 36 for BXE-2-32.")?;
        emit_seed_field(out, reg, "VERSION_ID", "Version ID. 29 for BXE-2-32.")?;
        emit_seed_field(
            out,
            reg,
            "NUMBER_OF_SCALABLE_UNITS",
            "Number of scalable units. 52 for BXE-2-32.",
        )?;
        emit_seed_field(out, reg, "CONFIG_ID", "Config ID. 182 for BXE-2-32.")?;
        out.push_str("}\n");
        return Ok(());
    }

    writeln!(
        out,
        "/// `{name}` — offset {off}.",
        name = reg.name,
        off = fmt_offset(reg.offset)
    )
    .unwrap();
    writeln!(out, "pub mod {mod_name} {{").unwrap();
    out.push_str("    use super::Field;\n");
    out.push('\n');
    out.push_str("    /// Register offset.\n");
    writeln!(
        out,
        "    pub const OFFSET: u32 = {};",
        fmt_offset(reg.offset)
    )
    .unwrap();

    for field in &reg.fields {
        writeln!(out, "    /// Bitfield `{}`.", field.name).unwrap();
        out.push_str("    pub const ");
        out.push_str(&field.name);
        out.push_str(": Field = Field {\n");
        writeln!(out, "        shift: {},", field.shift).unwrap();
        writeln!(out, "        mask: {},", fmt_u64_hex(field.mask())).unwrap();
        out.push_str("    };\n");
        if let Some(en) = field.en {
            writeln!(out, "    /// Upstream `{}_{}_EN`.", reg.name, field.name).unwrap();
            writeln!(
                out,
                "    pub const {}_EN: u64 = {};",
                field.name,
                fmt_u64_hex(en)
            )
            .unwrap();
        }
        for (vname, v) in &field.values {
            writeln!(
                out,
                "    /// Named value `{}_{}_{}`.",
                reg.name, field.name, vname
            )
            .unwrap();
            writeln!(
                out,
                "    pub const {}_{}: u64 = {};",
                field.name,
                vname,
                fmt_u64_hex(*v)
            )
            .unwrap();
        }
    }

    for (ident, upstream, v) in &reg.maskfulls {
        writeln!(out, "    /// Upstream `{upstream}`.").unwrap();
        writeln!(out, "    pub const {ident}: u64 = {};", fmt_u64_hex(*v)).unwrap();
    }

    for (cname, v) in &reg.constants {
        // Skip MASKFULL leftovers if any slipped through.
        if cname.contains("MASKFULL") {
            continue;
        }
        writeln!(out, "    /// Constant `{}_{}`.", reg.name, cname).unwrap();
        writeln!(out, "    pub const {}: u64 = {};", cname, fmt_u64_hex(*v)).unwrap();
    }

    out.push_str("}\n");
    Ok(())
}

fn emit_seed_field(
    out: &mut String,
    reg: &Register,
    name: &str,
    doc: &str,
) -> Result<(), ParseError> {
    let field = reg
        .fields
        .iter()
        .find(|f| f.name == name)
        .ok_or_else(|| ParseError(format!("seed field {name} missing on {}", reg.name)))?;
    // Verify parsed values match what the seed hard-codes, so a header change
    // cannot silently diverge from the round-trip expectation.
    let expected = match name {
        "BRANCH_ID" => (48u32, 0xffff_0000_0000_0000u64),
        "VERSION_ID" => (32, 0x0000_ffff_0000_0000),
        "NUMBER_OF_SCALABLE_UNITS" => (16, 0x0000_0000_ffff_0000),
        "CONFIG_ID" => (0, 0x0000_0000_0000_ffff),
        _ => unreachable!(),
    };
    if field.shift != expected.0 || field.mask() != expected.1 {
        return Err(ParseError(format!(
            "seed field {name}: parsed shift={} mask={} but seed expects shift={} mask={:#x}",
            field.shift,
            fmt_u64_hex(field.mask()),
            expected.0,
            expected.1
        )));
    }
    writeln!(out, "    /// {doc}").unwrap();
    out.push_str("    pub const ");
    out.push_str(name);
    out.push_str(": Field = Field {\n");
    writeln!(out, "        shift: {},", field.shift).unwrap();
    writeln!(out, "        mask: {},", fmt_u64_hex(field.mask())).unwrap();
    out.push_str("    };\n");
    Ok(())
}

/// Extract the `pub mod core_id_pbvnc { … }` block for round-trip checks.
pub fn extract_core_id_pbvnc_module(cr_rs: &str) -> Option<&str> {
    let start = cr_rs.find("/// `RGX_CR_CORE_ID` in its packed BVNC form.")?;
    let rest = &cr_rs[start..];
    let mod_start = rest.find("pub mod core_id_pbvnc {")?;
    let after = &rest[mod_start..];
    let mut depth = 0usize;
    let mut end = 0usize;
    for (i, c) in after.char_indices() {
        match c {
            '{' => depth += 1,
            '}' => {
                depth -= 1;
                if depth == 0 {
                    end = i + 1;
                    break;
                }
            }
            _ => {}
        }
    }
    if end == 0 {
        return None;
    }
    // Include the doc comment that precedes the module.
    Some(&cr_rs[start..start + mod_start + end])
}

pub fn emit_defs(
    src: &str,
    meta: &GenMeta<'_>,
    seed: &BTreeMap<String, u64>,
) -> Result<String, ParseError> {
    let map = parse_evaluable_defines(src, seed)?;
    let mut out = String::new();
    file_banner(
        &mut out,
        meta,
        "pvr_rogue_defs.h",
        "Assorted hardware constants: cache line sizes, alignment requirements, and\nthe interrupt status bits the IRQ handler decodes.",
        "https://elixir.bootlin.com/linux/latest/source/drivers/gpu/drm/imagination/pvr_rogue_defs.h",
    );
    // Only emit defines we successfully evaluated to integers. Function-like
    // macros and those depending on unavailable CR symbols are omitted by
    // design (not allow-listed); see parse_evaluable_defines.
    for (name, value) in &map {
        if name.starts_with("ROGUE_")
            || name.starts_with("MMU_")
            || name.starts_with("FWCORE_")
            || name.starts_with("BIF_")
            || name.starts_with("MAX_")
        {
            writeln!(out, "/// Upstream `{name}`.").unwrap();
            writeln!(out, "pub const {name}: u64 = {};", fmt_u64_hex(*value)).unwrap();
        }
    }
    Ok(out)
}

pub fn emit_mmu(src: &str, meta: &GenMeta<'_>) -> Result<String, ParseError> {
    let map = parse_evaluable_defines(src, &BTreeMap::new())?;
    let mut out = String::new();
    file_banner(
        &mut out,
        meta,
        "pvr_rogue_mmu_defs.h",
        "GPU MMU page-table entry formats.\n\nThe Rogue MMU uses three page-table levels over a 40-bit device address\nspace: page catalogue, page directory and page table. A leaf entry then\nnames the mapped page.",
        "https://elixir.bootlin.com/linux/latest/source/drivers/gpu/drm/imagination/pvr_rogue_mmu_defs.h",
    );
    if map.is_empty() {
        return Err(ParseError(
            "pvr_rogue_mmu_defs.h produced no constants".into(),
        ));
    }
    for (name, value) in &map {
        writeln!(out, "/// Upstream `{name}`.").unwrap();
        let ty = if *value <= u32::MAX as u64
            && !name.contains("CLRMSK")
            && !name.contains("EN")
            && !name.contains("MASK")
        {
            // Prefer u32 for small shifts / counts; keep u64 for masks.
            if name.contains("SHIFT")
                || name.contains("VALUE")
                || name.contains("SIZE")
                || name.contains("ENCODING")
                || name.contains("ALIGNSHIFT")
                || name.contains("ALIGNSIZE")
            {
                "u32"
            } else {
                "u64"
            }
        } else {
            "u64"
        };
        if ty == "u32" {
            writeln!(out, "pub const {name}: u32 = {value};").unwrap();
        } else {
            writeln!(out, "pub const {name}: u64 = {};", fmt_u64_hex(*value)).unwrap();
        }
    }
    Ok(out)
}

pub fn emit_mips(src: &str, meta: &GenMeta<'_>) -> Result<String, ParseError> {
    let map = parse_evaluable_defines(src, &BTreeMap::new())?;
    let mut out = String::new();
    file_banner(
        &mut out,
        meta,
        "pvr_rogue_mips.h",
        "MIPS firmware-processor definitions.\n\nBXE-2-32's firmware runs on a MIPS core, confirmed by the `MIPS_*` section\nIDs in the layout table of `rogue_36.29.52.182_v1.fw`. This module holds that\nprocessor's TLB entry format and its fixed address-space layout — the boot\nand exception vectors that the firmware image's own layout table refers to\n(`0xbfc00000`, `0x9fc02000`, `0xc0000000`).",
        "https://elixir.bootlin.com/linux/latest/source/drivers/gpu/drm/imagination/pvr_rogue_mips.h",
    );
    if map.is_empty() {
        return Err(ParseError("pvr_rogue_mips.h produced no constants".into()));
    }
    for (name, value) in &map {
        // Skip the string "MIPS" define if any slipped through — it won't.
        writeln!(out, "/// Upstream `{name}`.").unwrap();
        if *value <= u32::MAX as u64 {
            writeln!(out, "pub const {name}: u32 = {value:#x};").unwrap();
        } else {
            writeln!(out, "pub const {name}: u64 = {};", fmt_u64_hex(*value)).unwrap();
        }
    }
    Ok(out)
}

pub fn emit_heap(src: &str, meta: &GenMeta<'_>) -> Result<String, ParseError> {
    let map = parse_evaluable_defines(src, &BTreeMap::new())?;
    let mut out = String::new();
    file_banner(
        &mut out,
        meta,
        "pvr_rogue_heap_config.h",
        "Fixed GPU virtual address space layout.\n\nHeap bases and sizes are part of the firmware contract, not a policy we get\nto choose: the firmware and Mesa both assume these addresses. The values\nsurfaced to user space through `DRM_PVR_DEV_QUERY_HEAP_INFO_GET` come from\nhere.",
        "https://elixir.bootlin.com/linux/latest/source/drivers/gpu/drm/imagination/pvr_rogue_heap_config.h",
    );
    let expected = [
        "ROGUE_GENERAL_HEAP_BASE",
        "ROGUE_GENERAL_HEAP_SIZE",
        "ROGUE_PDSCODEDATA_HEAP_BASE",
        "ROGUE_PDSCODEDATA_HEAP_SIZE",
        "ROGUE_RGNHDR_HEAP_BASE",
        "ROGUE_RGNHDR_HEAP_SIZE",
        "ROGUE_USCCODE_HEAP_BASE",
        "ROGUE_USCCODE_HEAP_SIZE",
        "ROGUE_FW_HEAP_BASE",
        "ROGUE_TRANSFER_FRAG_HEAP_BASE",
        "ROGUE_TRANSFER_FRAG_HEAP_SIZE",
        "ROGUE_VISTEST_HEAP_BASE",
        "ROGUE_VISTEST_HEAP_SIZE",
    ];
    for name in expected {
        let Some(value) = map.get(name) else {
            return Err(ParseError(format!(
                "heap allow-list constant `{name}` missing or unevaluated"
            )));
        };
        writeln!(out, "/// Upstream `{name}`.").unwrap();
        writeln!(out, "pub const {name}: u64 = {};", fmt_u64_hex(*value)).unwrap();
    }
    Ok(out)
}

fn file_banner(
    out: &mut String,
    meta: &GenMeta<'_>,
    header: &str,
    module_doc: &str,
    reference: &str,
) {
    out.push_str("// SPDX-License-Identifier: MIT OR GPL-2.0-only\n");
    out.push_str("// Copyright (c) 2023 Imagination Technologies Ltd.\n");
    out.push_str("// K1 MUSE Book: generated PowerVR register and firmware ABI definitions.\n");
    out.push_str("//\n");
    out.push_str("// GENERATED by `pvr-regen` — DO NOT EDIT BY HAND.\n");
    writeln!(out, "// Source: {header}").unwrap();
    writeln!(out, "// Upstream commit: {}", meta.commit).unwrap();
    out.push_str("//\n");
    out.push_str("// File-level allow(dead_code): retain the complete selected definitions,\n");
    out.push_str("// including entries without a current runtime caller, so the generated\n");
    out.push_str("// interface remains consistent with its source allow-list.\n");
    out.push_str("#![allow(dead_code)]\n");
    out.push_str("// Preserve upstream macro spelling even when it is not UPPER_SNAKE.\n");
    out.push_str("#![allow(non_upper_case_globals)]\n");
    out.push('\n');
    out.push_str("//! ");
    let mut first = true;
    for line in module_doc.split('\n') {
        if first {
            out.push_str(line);
            out.push('\n');
            first = false;
        } else if line.is_empty() {
            out.push_str("//!\n");
        } else {
            out.push_str("//! ");
            out.push_str(line);
            out.push('\n');
        }
    }
    out.push_str("//!\n");
    writeln!(out, "//! Reference: <{reference}>.").unwrap();
    out.push('\n');
}
